// TH15 synthetic training aliases, copied from transcribe/th15/touhou-bullets.ecl.
// Source etSprite types used by this card: 7 (RING_BALL2) and 5 (BALL2).
const TH15_BALL2: int = 432;
const TH15_RING_BALL2: int = 464;

// th15_s1_w09 — TH15 v1.00b Stage 1 midstage wave 09.
// Source entry st01.ecl.txt:1140-1151 (MainSub07); deps:
//   GirlD02 615-638, GirlD02_at 640-686, MainSub01b 968-982,
//   Phantom01 1173-1195, Phantom01_at 1197-1216.
// Card frame 0 = source MainSub07 entry; source attack starts after the
// 120-frame independent shell buffer.
const TIME_LIMIT: int = 2124;   // 120 opening + 2000 schedule/tail estimate + 4 startup
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------------------
// source GirlD02 (615-638) + GirlD02_at (640-686)
// ---------------------------------------------------------------------------
async sub girl_d02() {
    set_invuln(65535);
    set_hurtbox(16fx);   // setHurtbox(32,32): modern round rule, first value * 0.5
    set_hitbox(12fx);    // setHitbox(24,24): first value * 0.5
    move_vel(0, 90deg, 3fx, EASE_LINEAR);       // moveVel(pi/2, 3)
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);     // moveVelTime(80, mode 1, pi/2, 0)
    spawn girl_d02_at();                        // @GirlD02_at() async
    wait(240);
    move_speed(120, -1fx, EASE_QUAD_IN);        // moveSpeedTime(120, mode 1, -1)
    wait(60);
    loop { wait(1000); }                        // GirlD02_440 -> GirlD02_420 idle loop
}

async sub girl_d02_at() {
    wait(60);
    // diffI($A, 2, 5, 8, 4); etCount layers 2/6/8/6; etSpeed s0 1.6/1.6/3.0/4.0;
    // shot interval 120/120/60/30.
    var rank: int = global(GVAR_RANK);
    var shots: int = 2;
    var layers: int = 2;
    var s0: fx = 1.6fx;
    var interval: int = 120;
    if rank == RANK_NORMAL {
        shots = 5; layers = 6; s0 = 1.6fx; interval = 120;
    } else if rank == RANK_HARD {
        shots = 8; layers = 8; s0 = 3fx; interval = 60;
    } else if rank == RANK_LUNATIC {
        shots = 4; layers = 6; s0 = 4fx; interval = 30;
    }
    while shots > 0 {
        shots = shots - 1;
        girl_wave(layers, s0);   // etOn(0)
        wait(interval);
    }
}

// etAim(0, 9): aimed alternating-layer ring, N = 8 ways, alpha = 0,
// delta = 0.05235988 rad (3 deg); layer speeds from s0 to 1.6.
sub girl_wave(layers: int, s0: fx) {
    var aim_i: int = aim_player() as int;
    var delta: int = 3deg as int;
    var half: int = delta / 2;
    for q in 0..layers {
        var h: int = 0;
        if layers % 2 == 0 {
            h = ((q / 2) * 2 + 1) * half;   // (floor(q/2) + 1/2) * delta
        } else {
            h = ((q + 1) / 2) * delta;      // floor((q+1)/2) * delta
        }
        var k: int = 0;
        if layers % 2 == 0 {
            k = (q / 2) * 2;
        } else {
            k = ((q + 1) / 2) * 2;
        }
        var spd: fx = s0;
        if layers > 1 {
            spd = s0 + (1.6fx - s0) * (k as fx) / (layers - 1);
        }
        for i in 0..8 {
            var a: int = i * 8192 + h;      // R(i) = i * 65536 / 8
            if q % 2 != 0 { a = 0 - a; }    // (-1)^q on the whole R + H
            _ = fire(TH15_RING_BALL2, 2, $self_x, $self_y, spd, (aim_i + a) as angle, none, none);
        }
    }
}

// ---------------------------------------------------------------------------
// source MainSub01b (968-982): nine mirrored Phantom01 pairs, 30 frames apart
// ---------------------------------------------------------------------------
async sub phantom_wave() {
    var a: int = 0;
    var b: int = 9;
    while b > 0 {                     // if ($B--) goto ...
        b = b - 1;
        a = a + 16;
        _ = spawn_enemy(a as fx, -24fx, 90, 0, 1000, 0, phantom01);
        _ = spawn_enemy((0 - a) as fx, -24fx, 90, 0, 1000, 0, phantom01);
        wait(30);
    }
}

// ---------------------------------------------------------------------------
// source Phantom01 (1173-1195) + Phantom01_at (1197-1216)
// ---------------------------------------------------------------------------
async sub phantom01() {
    set_invuln(65535);
    set_hurtbox(14fx);   // setHurtbox(28,28): 28 * 0.5
    set_hitbox(8fx);     // setHitbox(16,16): 16 * 0.5
    if global(GVAR_RANK) >= RANK_HARD {
        spawn phantom01_at();   // !HL only
    }

    // moveVel(pi/2, 1) + moveVelTime(120, mode 3, pi/2, 1.5) give the ABS
    // descent; moveEllipseRel(F0, 0.034906585, 10, 0, ABS_ANGLE, 0) adds the
    // s=0 fixed-axis sway. F0 snapshot is 0.017446 rad (1 deg) from main,
    // ABS_ANGLE is pi/2 at set time, so the REL offset is x = 10*cos(theta).
    var x0: fx = $self_x;
    var y0: fx = $self_y;
    var theta: angle = 1deg;   // %F0 = 0.087266 - 20*0.003491
    move_to(0, x0 + 10fx * cos(theta), y0, EASE_LINEAR);
    var tick: int = 0;
    loop {
        tick = tick + 1;
        var vy: fx = 1.5fx;
        if tick <= 120 {
            var t: fx = (tick as fx) / 120;
            vy = 1fx + 0.5fx * t * t * t * t;   // quart-in 1.0 -> 1.5
        }
        theta = theta + 2deg;                   // omega = 0.034906585 rad/frame
        var nx: fx = x0 + 10fx * cos(theta);
        move_vel_xy(0, nx - $self_x, vy, EASE_LINEAR);
        wait(1);
    }
}

async sub phantom01_at() {
    // etCountD layers 1/1/1/8, etSpeedD 3.0->1.0; diffI($A,1,1,1,2).
    // Only reached on Hard/Lunatic, so layers = 1/8 and shots = 1/2.
    var shots: int = 1;
    var layers: int = 1;
    if global(GVAR_RANK) == RANK_LUNATIC {
        shots = 2;
        layers = 8;
    }
    while shots > 0 {
        shots = shots - 1;
        wait(60 + rand(90));          // wait(60 + ($RAND % 90))
        var aim: angle = aim_player();   // etAim(0, 0) resolves at etOn, N = 1
        for q in 0..layers {
            var spd: fx = 3fx;
            if layers > 1 {
                spd = 3fx + (1fx - 3fx) * (q as fx) / (layers - 1);
            }
            _ = fire(TH15_BALL2, 4, $self_x, $self_y, spd, aim, none, none);
        }
    }
}

// ---------------------------------------------------------------------------
// source MainSub07 (1140-1151): schedule
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-64fx, -24fx, 1100, 0, 1000, 0, girl_d02);
    _ = spawn_enemy(64fx, -24fx, 1100, 0, 1000, 0, girl_d02);
    wait(60);
    spawn phantom_wave();    // @MainSub01b() async
    wait(300);
    _ = spawn_enemy(-120fx, -24fx, 1100, 0, 1000, 0, girl_d02);
    _ = spawn_enemy(120fx, -24fx, 1100, 0, 1000, 0, girl_d02);
    wait(60);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
